        collection = self._collection(parts)
        try:
            return _get_collection_metadata(collection)
        except ValueError as exc:
            raise AnsibleError('unable to locate collection %s: %s' % (collection, exc))

    def _redirect(self, parts):
        if len(parts) <= 5:
            return None
        routing = self._metadata(parts).get('plugin_routing', {}).get('module_utils', {}).get('.'.join(parts[5:]), {})
        return self._make_redirect(parts, routing, self._collection(parts)) if routing else None

    def _local(self, parts):
        if len(parts) < 3:
            return None
        self._metadata(parts)
        # The namespace, collection and plugins directories may be implicit packages.
        if len(parts) <= 5:
            return b'', '<implicit package>', True, None
        package = 'ansible_collections.' + self._collection(parts)
        try:
            roots = importlib.import_module(package).__path__
        except ImportError:
            raise AnsibleError('unable to locate collection %s' % self._collection(parts))
